let GENDER = 'f';                       // f = بنات · m = بنين · n = مشترك
let _RX = null, _MAP = null;
/* يُبنى تعبير نمطي واحد بترتيب الأطول أولًا — تمريرة واحدة تمنع إعادة استبدال ما استُبدل */
const _DIAC = /[\\u064B-\\u0652\\u0670\\u0640]/g;
const _bare = s => String(s).replace(_DIAC, '');
function buildLex(){
  const i = {f:1, m:2, n:3}[GENDER];
  const rows = [...LEX].sort((a,b)=>_bare(b[0]).length - _bare(a[0]).length);
  _MAP = {}; rows.forEach(r=>{ const k=_bare(r[0]); if(!(k in _MAP)) _MAP[k] = r[i]; });
  const esc = x => x.replace(/[.*+?^\${}()|[\\]\\\\]/g,'\\\\$&');
  /* السماح بأي تشكيل بين الحروف حتى يتطابق «رتِّبي» مع «رتبي» */
  const D = '[\\\\u064B-\\\\u0652\\\\u0670\\\\u0640]*';
  const pat = w => _bare(w).split('').map(c => esc(c) + D).join('');
  /* حدود الكلمة تمنع مطابقة الاسم داخل كلمة أخرى (هند ≠ المهندس) */
  /* السماح بحرفَي العطف «و» و«ف» قبل الكلمة */
  _RX = new RegExp('(?<![\\\\p{L}])([وف])?('+rows.map(r=>pat(r[0])).join('|')+')(?![\\\\p{L}])','gu');
}
/* gx: يحوّل أي نص إلى صيغة المسار المختار — بلا حساسية للتشكيل */
function gx(t){
  if(!t) return t;
  const S = String(t);
  /* المقاطعُ المحميَّة: ﴿آية﴾ · «اقتباس» · “اقتباس” */
  const RX_Q = /﴿[^﴾]*﴾|«[^»]*»|“[^”]*”/g;
  const conv = x => String(x).replace(_RX, (m, pre, w) => {
    const v = _MAP[_bare(w)];
    if (v === undefined) return m;
    return (pre || '') + v;
  });
  let out = '', last = 0, m;
  RX_Q.lastIndex = 0;
  while ((m = RX_Q.exec(S)) !== null) {
    out += conv(S.slice(last, m.index)) + m[0];
    last = m.index + m[0].length;
  }
  out += conv(S.slice(last));
  return out;
}
const GENDER_LBL = {f:'بنات', m:'بنين', n:'مشترك'};
