/* صورة جاهزة: تُرسم كما هي — بلا إطار ولا ترويسة ولا تذييل */
const IMG_AR = {};   /* نسبة العرض للارتفاع لكل صورة — تُقاس تلقائيًا */
function imgDesign(t, s){
  const src = PHOTOS[t.img] || '';
  const por = /^(bh|bs|bm)\\d/.test(String(t.img||''));   /* بطاقات A4 طولية */
  const W = por ? 560 : 760;
  const H = por ? Math.round(W*1168/880) : Math.round(W*9/16);
  return '<div class="design imgraw" style="width:'+W+'px;height:'+H+'px">'+
         (src?'<img src="'+src+'" alt="">':'')+'</div>';
}
/* تحميل الصورة بجودتها الأصلية بصيغة JPG */
function dlImage(){
  const t = S.cur; if(!t || !t.img) return;
  const src = PHOTOS[t.img]; if(!src) return toast('⚠️','الصورة غير متوفرة');
  const im = new Image();
  im.onload = () => {
    const c = document.createElement('canvas'); c.width=im.width; c.height=im.height;
    const x = c.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,c.width,c.height); x.drawImage(im,0,0);
    const a = document.createElement('a');
    a.href = c.toDataURL('image/jpeg',0.94);
    a.download = String(t.name||'صورة').replace(/[\\\\/:*?"<>|]/g,'-') + '.jpg';
    document.body.appendChild(a); a.click(); a.remove();
    toast('⬇','تم تحميل الصورة بجودتها الأصلية');
  };
  im.onerror = () => toast('⚠️','تعذّر تحميل الصورة');
  im.src = src;
}


